import numpy as np
from collections import Counter
def frames(a,bg=None):
    a=np.array(a); bg=a.flat[0] if False else a[a==a.flat[0]].min() if True else None
    H,W=a.shape
    # background = most common color
    cnt=Counter(a.flat); bg=cnt.most_common(1)[0][0]
    res=[]
    for r0 in range(H-2):
        for c0 in range(W-2):
            for h in range(3,H-r0+1):
                for w in range(3,W-c0+1):
                    sub=a[r0:r0+h,c0:c0+w]; v=sub[0,0]
                    if (sub[0]==v).all() and (sub[-1]==v).all() and (sub[:,0]==v).all() and (sub[:,-1]==v).all():
                        inn=sub[1:-1,1:-1]
                        u=set(inn.flat-{v})
                        res.append(dict(loc=(r0,c0,h,w),col=int(v),inner=u))
    return res
